import fs from 'fs-extra';
import path from 'path';

const packageJson = fs.readJsonSync('./package.json');
const version = packageJson.version;
const majorVersion = `v${version.split('.')[0]}`;
const outputDir = 'dist';

async function organizeCDNFiles() {
  const versionDir = path.join(outputDir, `${majorVersion}.${version}`);
  const majorDir = path.join(outputDir, majorVersion);

  // Ensure version-specific directory exists
  await fs.ensureDir(versionDir);

  // Copy the build output to version-specific directory
  await fs.copy(path.join(outputDir, 'my-library.umd.js'), path.join(versionDir, 'my-library.min.js'));

  // Copy the latest version to major version directory
  await fs.ensureDir(majorDir);
  await fs.copy(path.join(outputDir, 'my-library.umd.js'), path.join(majorDir, 'my-library.min.js'));

  console.log(`CDN files organized for version ${version}`);
}

organizeCDNFiles().catch(console.error);

