  <h1>Hacker News Top 50 (live)</h1>
  <ol id="stories"></ol>

  <script>
    const API_TOP = 'https://hacker-news.firebaseio.com/v0/topstories.json';
    const API_ITEM = id => `https://hacker-news.firebaseio.com/v0/item/${id}.json`;
    const POSTS_TO_FETCH = 50;

    // kick off immediately
    loadTopstories().catch(console.error);

    async function loadTopstories() {
      const res  = await fetch(API_TOP);
      const ids  = await res.json();
      const list = document.getElementById('stories');

      ids.slice(0, POSTS_TO_FETCH).forEach(id => {
        // placeholder element keeps ranking stable while we wait
        const li = document.createElement('li');
        li.id = `story-${id}`;
        li.innerHTML = `<span class="loading">Loading…</span>`;
        list.appendChild(li);
        fetchStory(id, li);
      });
    }

    async function fetchStory(id, li) {
      try {
        const res   = await fetch(API_ITEM(id));
        const story = await res.json();
        if (!story) return;

        li.innerHTML = `
          <a href="${story.url || `https://news.ycombinator.com/item?id=${id}`}" target="_blank" rel="noopener">
            ${escapeHTML(story.title)}
          </a>
          <div class="sub">
            ${story.score} points by
            <a href="https://news.ycombinator.com/user?id=${story.by}" target="_blank" rel="noopener">${story.by}</a>
            • <a href="https://news.ycombinator.com/item?id=${id}" target="_blank" rel="noopener">
                ${story.descendants ?? 0} comments
              </a>
            • ${timeAgo(story.time)}
          </div>`;
      } catch (err) {
        li.innerHTML = `<span class="loading">Failed to load story (#${id})</span>`;
        console.error(err);
      }
    }

    // --- helpers -----------------------------------------------------------

    function timeAgo(unixSeconds) {
      const seconds = Math.floor(Date.now() / 1000) - unixSeconds;
      const intervals = [
        { d: 60,    n: 'second' },
        { d: 60,    n: 'minute' },
        { d: 24,    n: 'hour'   },
        { d: 7,     n: 'day'    },
        { d: 4.345, n: 'week'   },
        { d: 12,    n: 'month'  },
        { d: 1e9,   n: 'year'   } // effectively “else”
      ];
      let count = seconds, i = 0;
      while (count >= intervals[i].d) {
        count /= intervals[i].d;
        i++;
      }
      count = Math.floor(count);
      const unit = intervals[i].n + (count !== 1 ? 's' : '');
      return `${count} ${unit} ago`;
    }

    function escapeHTML(str) {
      return str.replace(/[&<>"']/g, c => ({
        '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
      }[c]));
    }
  </script>
</body>
</html>

