            setupGainNodes();
            automateFadeIn(2); // Fade in for 2 seconds
        }

        function stopNoise() {
            if (noiseProcessor) {
                automateFadeOut(2); // Fade out for 2 seconds
                setTimeout(function () {
                    noiseProcessor.disconnect();
                    noiseProcessor = null;
                    gainNodes.forEach(function (gainNode) {
