        function createBandpassFilter(lowFreq, highFreq) {
            var filter = context.createBiquadFilter();
            filter.type = 'bandpass';
            filter.frequency.value = (lowFreq + highFreq) / 2;
            filter.Q.value = filter.frequency.value / (highFreq - lowFreq);
            return filter;
