                        return value.toFixed(2);
                    },
                    from: function (value) {
                        return Number(value);
                    }
                }
            });

            container.noUiSlider.on('update', function (values, handle, unencoded, isTap, positions) {
                var value = parseFloat(values[handle]);
                valueIndicator.textContent = value.toFixed(2);
                if (gainNodes[index]) {
