    document.querySelectorAll('.chapter-title').forEach((chapter, index) => {
      const chapterHash = chapter.getAttribute('data-hash');
      const progress = data.find(item => item.chapterHash === chapterHash);

      // Add progress indicators dynamically
      if (progress) {
        const status = document.createElement('span');
        status.className = progress.completed ? 'completed' : 'not-completed';
        status.innerText = progress.completed ? '✓ Completed' : 'In Progress';
