export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Only affect normal page navigations (HTML). Leave API/assets alone.
    const accept = request.headers.get("accept") || "";
    const isHTML = accept.includes("text/html");

    // Skip obvious non-page paths (adjust to your app)
    const skipPrefixes = ["/api", "/assets", "/_app", "/fonts", "/images", "/favicon", "/robots.txt", "/sitemap"];
    const shouldSkip = skipPrefixes.some((p) => url.pathname.startsWith(p));
    if (!isHTML || shouldSkip) {
      return fetch(request);
    }

    // Detect login by cookie (adjust)
    const cookie = request.headers.get("cookie") || "";
    const AUTH_COOKIE_REGEX = /(session=|__session=|firebase:auth|authToken=)/i;
    const isLoggedIn = AUTH_COOKIE_REGEX.test(cookie);

    if (isLoggedIn) {
      // Logged-in: serve the app normally
      return fetch(request);
    }

    // Logged-out: proxy the marketing site
    const aboutUrl = new URL(request.url);
    aboutUrl.hostname = "about.betarena.com";
    // Usually you want the marketing home for any logged-out landing:
    // aboutUrl.pathname = "/";

    // Fetch from about site (preserve path if you want deep links)
    const aboutReq = new Request(aboutUrl.toString(), {
      method: "GET",
      headers: new Headers(request.headers),
      redirect: "manual",
    });

    // Set Host properly (some setups care)
    aboutReq.headers.set("host", "about.betarena.com");

    const res = await fetch(aboutReq);

    // Clone headers so we can tweak caching + SEO safety
    const headers = new Headers(res.headers);

    // Cache strategy:
    // - logged-out marketing can be cached publicly
    // - avoid mixing with logged-in content (we already branch, but be explicit)
    headers.set("Cache-Control", "public, s-maxage=300, max-age=0"); // 5 min at edge
    headers.append("Vary", "Accept"); // helps prevent weird caching

    return new Response(res.body, { status: res.status, headers });
  },
};

