export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Only the homepage
    if (url.pathname !== "/") return fetch(request);

    // Only normal page loads (not assets / fetches)
    const accept = request.headers.get("accept") || "";
    if (!accept.includes("text/html")) return fetch(request);

    // Detect login by cookie (adjust this)
    const cookie = request.headers.get("cookie") || "";
    const AUTH_COOKIE_REGEX = /(session=|__session=|firebase:auth|authToken=)/i;
    const isLoggedIn = AUTH_COOKIE_REGEX.test(cookie);

    if (isLoggedIn) {
      // Logged-in -> serve app home
      return fetch(request);
    }

    // Logged-out -> serve marketing home (proxy)
    const aboutUrl = new URL("https://about.betarena.com/");

    const aboutReq = new Request(aboutUrl.toString(), {
      method: "GET",
      headers: request.headers,
    });

    // Some origins care about Host
    aboutReq.headers.set("host", "about.betarena.com");

    const res = await fetch(aboutReq);

    const headers = new Headers(res.headers);

    // Safe caching: cache marketing for anonymous users at edge
    headers.set("Cache-Control", "public, s-maxage=300, max-age=0");
    headers.append("Vary", "Accept");

    return new Response(res.body, { status: res.status, headers });
  },
};

