using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Collections.Generic;

public class LibreTranslateService
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const string ApiUrl = "https://libretranslate.com/detect"; // Change this to your LibreTranslate API URL if self-hosting

    public class LanguageDetectionResult
    {
        public string Language { get; set; }
        public float Confidence { get; set; }
    }

    public static async Task<string> DetectLanguageAsync(string text)
    {
        var data = new Dictionary<string, string>
        {
            { "q", text }
        };

        var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync(ApiUrl, content);
        var responseString = await response.Content.ReadAsStringAsync();

        var result = JsonConvert.DeserializeObject<List<LanguageDetectionResult>>(responseString);
        return result?.Count > 0 ? result[0].Language : "unknown";
    }
}

